290	func indexConfigObjects(ptr any, configPath string, index map[string]string) error {
291		switch val := ptr.(type) {
292		case map[string]any:
293			for k, v := range val {
294				if k == idKey {
295					var idStr string
296					switch idVal := v.(type) {
