			name:        "duplicate listener validation",
			contentType: "application/json",
			body: fmt.Sprintf(`{"apps":{"http":{"servers":{
				"one":{"listen":[%q],"routes":[]},
				"two":{"listen":[%q],"routes":[]}
			}}}}`, clH2SiteAddr, clH2SiteAddr),
			wantErr: "listener address repeated",
		},
	}
