package caddyconfig

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/caddyserver/caddy/v2"
)

// TestHandleLoadRejectsMalformedPayloads verifies that malformed documents
// are refused with a 400 APIError before any running configuration is
// touched. None of these cases may reach caddy.Load, so they must not mutate
// process state regardless of what (if anything) is currently running.
func TestHandleLoadRejectsMalformedPayloads(t *testing.T) {
	var al adminLoad

	for i, tc := range []struct {
		name        string
		contentType string
		body        string
		wantErr     string
	}{
		{
			name:        "empty body",
			contentType: "application/json",
			body:        "",
			wantErr:     "request body is empty",
		},
		{
			name:        "whitespace only",
			contentType: "application/json",
			body:        "   \n\t ",
			wantErr:     "request body is empty",
		},
		{
			name:        "empty Caddyfile body",
			contentType: "text/caddyfile",
			body:        "",
			wantErr:     "request body is empty",
		},
		{
			name:        "null document",
			contentType: "application/json",
			body:        "null",
			wantErr:     "configuration must be a JSON object, got null",
		},
		{
			name:        "truncated JSON",
			contentType: "application/json",
			body:        `{"apps":`,
			wantErr:     "unexpected end of JSON input",
		},
		{
			name:        "trailing data",
			contentType: "application/json",
			body:        `{"apps":{}}GARBAGE`,
			wantErr:     "after top-level value",
		},
		{
			name:        "non-object array",
			contentType: "application/json",
			body:        `[1,2,3]`,
			wantErr:     "configuration must be a JSON object",
		},
		{
			name:        "wrong method",
			contentType: "application/json",
			body:        `{}`,
			wantErr:     "method not allowed",
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			method := http.MethodPost
			if tc.name == "wrong method" {
				method = http.MethodGet
			}
			req := httptest.NewRequest(method, "/load", strings.NewReader(tc.body))
			if tc.contentType != "" {
				req.Header.Set("Content-Type", tc.contentType)
			}
			rec := httptest.NewRecorder()

			err := al.handleLoad(rec, req)
			if err == nil {
				t.Fatalf("case %d (%s): expected an error, got nil; status=%d", i, tc.name, rec.Code)
			}
			apiErr, ok := err.(caddy.APIError)
			if !ok {
				t.Fatalf("case %d (%s): error is not an APIError: %T %v", i, tc.name, err, err)
			}
			if apiErr.HTTPStatus != http.StatusBadRequest {
				t.Fatalf("case %d (%s): status: got %d, want %d", i, tc.name, apiErr.HTTPStatus, http.StatusBadRequest)
			}
			if !strings.Contains(apiErr.Error(), tc.wantErr) {
				t.Fatalf("case %d (%s): error: got %q, want it to contain %q", i, tc.name, apiErr.Error(), tc.wantErr)
			}
		})
	}
}

