368	// adminHandlerSwitch holds an adminHandler behind an atomic pointer so a
369	// running admin server can keep its listener across configuration loads
370	// that do not change its address: only the handler is swapped at commit.
371	// This means a rolled-back load never has to close the listener that is
372	// currently serving the very request that submitted the bad config.
373	type adminHandlerSwitch struct {
374		value atomic.Pointer[adminHandler]
375	}
376	
377	func (s *adminHandlerSwitch) ServeHTTP(w http.ResponseWriter, r *http.Request) {
378		s.value.Load().ServeHTTP(w, r)
379	}
380	
381	// localAdminChange is a prepared replacement of the local admin endpoint.
382	// It has no effect until commit is called; if the new configuration fails
383	// before it is committed, rollback leaves the previously running admin
384	// endpoint - its listener, its server and its handler - untouched.
385	type localAdminChange struct {
386		// disable is set when the new configuration turns the endpoint off
387		disable bool
388	
389		// switcher and handler are set when the address is unchanged: the
390		// running server keeps serving and commit atomically swaps in the
391		// new handler; rollback has nothing to undo because the new handler
392		// was never published
393		switcher *adminHandlerSwitch
394		handler  adminHandler
395	
396		// newServer is set at initial startup or when the address changes:
397		// commit publishes the server and stops the previous one, while
398		// rollback closes this prepared server without touching the old one
399		newServer *http.Server
400		addr      NetworkAddress
401	
402		// copied from the prepared handler for the startup log
403		enforceOrigin bool
404	}
405	
406	// prepareLocalAdminServer provisions the local admin endpoint described by
407	// cfg without disturbing the endpoint that is currently running. If no
408	// configuration for the admin endpoint exists in cfg, a default one is
409	// used, so there is always an admin server (unless it is explicitly
410	// configured to be disabled).
411	// Critically note that some elements and functionality of the context
412	// may not be ready, e.g. storage. Tread carefully.
413	func prepareLocalAdminServer(cfg *Config, ctx Context) (*localAdminChange, error) {
414		// set a default if admin wasn't otherwise configured
415		if cfg.Admin == nil {
416			cfg.Admin = &AdminConfig{
417				Listen: DefaultAdminListen,
418			}
419		}
420	
421		// if new admin endpoint is to be disabled, nothing to prepare;
422		// commit stops the running endpoint (rollback therefore has
423		// nothing to undo)
424		if cfg.Admin.Disabled {
425			Log().Named("admin").Warn("admin endpoint will be disabled")
426			return &localAdminChange{disable: true}, nil
427		}
428	
429		// extract a singular listener address
430		addr, err := parseAdminListenAddr(cfg.Admin.Listen, DefaultAdminListen)
431		if err != nil {
432			return nil, err
433		}
434	
435		handler, err := cfg.Admin.newAdminHandler(addr, false, ctx)
436		if err != nil {
437			return nil, err
438		}
439	
440		change := &localAdminChange{
441			handler:       handler,
442			addr:          addr,
443			enforceOrigin: cfg.Admin.EnforceOrigin,
444		}
445	
446		// when the address does not change, the running server keeps its
447		// listener and only its (atomically swappable) handler needs to be
448		// replaced at commit; no socket is (re)bound, so a rolled-back load
449		// cannot interrupt or answer the connection that submitted it
450		serverMu.Lock()
451		current := localAdminServer
452		serverMu.Unlock()
453		if current != nil && current.Addr == addr.String() {
454			switcher, ok := current.Handler.(*adminHandlerSwitch)
455			if !ok {
456				return nil, fmt.Errorf("internal: unexpected admin handler type %T", current.Handler)
457			}
458			change.switcher = switcher
459			return change, nil
460		}
461	
462		ln, err := addr.Listen(context.TODO(), 0, net.ListenConfig{})
463		if err != nil {
464			return nil, err
465		}
466	
467		switcher := new(adminHandlerSwitch)
468		switcher.value.Store(&handler)
469	
470		server := &http.Server{
471			Addr:              addr.String(), // for logging purposes only
472			Handler:           switcher,
473			ReadTimeout:       10 * time.Second,
474			ReadHeaderTimeout: 5 * time.Second,
475			IdleTimeout:       60 * time.Second,
476			MaxHeaderBytes:    1024 * 64,
477		}
478		change.newServer = server
479	
480		adminLogger := Log().Named("admin")
481		go func() {
482			if err := server.Serve(ln.(net.Listener)); !errors.Is(err, http.ErrServerClosed) {
483				adminLogger.Error("admin server shutdown for unknown reason", zap.Error(err))
484			}
485		}()
486	
487		return change, nil
488	}
489	
490	// commit publishes the prepared admin endpoint: it either swaps the handler
491	// of the still-running server in place, starts serving a newly prepared
492	// server and stops the previous one, or stops the previous one when the
493	// endpoint is disabled.
494	func (change *localAdminChange) commit() {
495		if change == nil {
496			return
497		}
498	
499		adminLogger := Log().Named("admin")
500	
501		// same address: atomically publish the new handler on the
502		// existing server, without touching its listener
503		if change.switcher != nil {
504			change.switcher.value.Store(&change.handler)
505			adminLogger.Info("admin endpoint updated",
506				zap.String("address", change.addr.String()))
507			return
508		}
509	
510		serverMu.Lock()
511		oldAdminServer := localAdminServer
512		if change.disable {
513			localAdminServer = nil
514		} else {
515			localAdminServer = change.newServer
516		}
517		serverMu.Unlock()
518	
519		// shut down the old endpoint asynchronously so any current API
520		// request (potentially the one that triggered this commit) gets
521		// its response; this goroutine may last a few seconds
522		if oldAdminServer != nil {
523			go func(oldAdminServer *http.Server) {
524				if err := stopAdminServer(oldAdminServer); err != nil {
525					Log().Named("admin").Error("stopping current admin endpoint", zap.Error(err))
526				}
527			}(oldAdminServer)
528		}
529	
530		if change.disable {
531			adminLogger.Warn("admin endpoint disabled")
532			return
533		}
534	
535		adminLogger.Info("admin endpoint started",
536			zap.String("address", change.addr.String()),
537			zap.Bool("enforce_origin", change.enforceOrigin),
538			zap.Array("origins", loggableURLArray(change.handler.allowedOrigins)))
539	
540		if !change.handler.enforceHost {
541			adminLogger.Warn("admin endpoint on open interface; host checking disabled",
542				zap.String("address", change.addr.String()))
543		}
544	}
545	
546	// rollback abandons a prepared admin endpoint after the new configuration
547	// failed. A same-address preparation never published its handler and a
548	// disabling preparation never stopped the old endpoint, so they need no
549	// cleanup; a freshly started server (different address or initial startup)
550	// is drained and closed asynchronously while the previous endpoint keeps
551	// serving.
552	func (change *localAdminChange) rollback() {
553		if change == nil || change.newServer == nil {
554			return
555		}
